from __future__ import annotations

import glob
import os
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Iterator, Tuple

from . import byte_codes, config


@dataclass(frozen=True)
class FileInfo:
	"""Metadata for a database file.

	The object is also iterable so older code can still unpack it like:
	`json_path, json_exists, ddb_path, ddb_exists = file_info("users")`.
	"""

	json_path: str
	json_exists: bool
	ddb_path: str
	ddb_exists: bool
	storage_path: str | None = None
	size_bytes: int | None = None
	created_time: datetime | None = None
	modified_time: datetime | None = None
	is_directory: bool = False
	is_file: bool = False

	def __iter__(self) -> Iterator[str | bool]:
		yield self.json_path
		yield self.json_exists
		yield self.ddb_path
		yield self.ddb_exists

	def __bool__(self) -> bool:
		return self.json_exists or self.ddb_exists or self.is_directory


def _resolve_relative_path(db_name: str) -> str:
	"""Return the storage-relative path without file extension."""
	return os.path.normpath(os.path.join(config.storage_directory, db_name))


def _get_storage_path(db_name: str) -> str:
	"""Return the currently active storage path if it exists, else the JSON path."""
	info = file_info(db_name)
	return info.storage_path or info.json_path


def _normalize_relative_path(path: str) -> str:
	return path.replace("\\", "/")


def file_info(db_name: str) -> FileInfo:
	"""
	Return metadata for the JSON and compressed variants of a database file.

	The first four values remain compatible with the historical tuple return:
	`(json_path, json_exists, ddb_path, ddb_exists)`.
	"""

	base = _resolve_relative_path(db_name)
	json_path = f"{base}.json"
	ddb_path = f"{base}.ddb"
	json_exists = os.path.exists(json_path)
	ddb_exists = os.path.exists(ddb_path)
	storage_path = json_path if json_exists else ddb_path if ddb_exists else None

	size_bytes = None
	created_time = None
	modified_time = None
	is_directory = os.path.isdir(base)
	is_file = False
	if storage_path is not None:
		stat = os.stat(storage_path)
		size_bytes = stat.st_size
		created_time = datetime.fromtimestamp(stat.st_ctime, tz=timezone.utc)
		modified_time = datetime.fromtimestamp(stat.st_mtime, tz=timezone.utc)
		is_file = os.path.isfile(storage_path)

	return FileInfo(
		json_path=json_path,
		json_exists=json_exists,
		ddb_path=ddb_path,
		ddb_exists=ddb_exists,
		storage_path=storage_path,
		size_bytes=size_bytes,
		created_time=created_time,
		modified_time=modified_time,
		is_directory=is_directory,
		is_file=is_file,
	)


def file_exists(db_name: str) -> bool:
	"""
	Return ``True`` if the database exists as JSON or compressed storage.

	Wildcard paths are treated as glob patterns and return ``True`` when at least
	one matching file exists.
	"""

	if "*" in db_name:
		return bool(find_all(db_name))
	_, json_exists, _, ddb_exists = file_info(db_name)
	return json_exists or ddb_exists


def find_all(file_name: str) -> list[str]:
	"""
	Return all matching database names for the provided glob pattern.

	Returned names are relative to ``config.storage_directory`` and have no file
	extension.
	"""

	base_pattern = _resolve_relative_path(file_name)
	files_all = glob.glob(f"{base_pattern}.ddb")
	files_all += glob.glob(f"{base_pattern}.json")
	files_all = sorted(set(files_all))
	results = []
	for path in files_all:
		relative = os.path.relpath(path, config.storage_directory)
		if relative.endswith(".ddb"):
			relative = relative[:-4]
		elif relative.endswith(".json"):
			relative = relative[:-5]
		results.append(_normalize_relative_path(relative))
	return results


def seek_index_through_value_bytes(json_bytes: bytes, index: int) -> int:
	"""
	Find the end index of the JSON value starting at ``index``.
	"""

	list_depth, dict_depth, i, len_json_bytes = 0, 0, index, len(json_bytes)

	while i < len_json_bytes:
		current = json_bytes[i]
		if current == byte_codes.BACKSLASH:
			i += 1

		elif current == byte_codes.QUOTE:
			while True:
				i = json_bytes.find(bytes([byte_codes.QUOTE]), i + 1)
				if i == -1:
					raise TypeError("Invalid JSON")

				j = i - 1
				backslash_count = 0
				while j >= 0 and json_bytes[j] == byte_codes.BACKSLASH:
					backslash_count += 1
					j -= 1
				if backslash_count % 2 == 0:
					break

			if list_depth == 0 and dict_depth == 0:
				return i + 1

		elif current == byte_codes.OPEN_SQUARE:
			list_depth += 1
		elif current == byte_codes.OPEN_CURLY:
			dict_depth += 1
		elif current == byte_codes.CLOSE_SQUARE:
			list_depth -= 1
			if list_depth == 0 and dict_depth <= 0:
				return i + 1 + dict_depth
		elif current == byte_codes.CLOSE_CURLY:
			dict_depth -= 1
			if dict_depth <= 0 and list_depth == 0:
				return i + 1 + dict_depth
		elif list_depth == 0:
			if dict_depth == -1:
				return i
			if dict_depth == 0 and current in [byte_codes.COMMA, byte_codes.NEWLINE]:
				return i
		i += 1

	raise TypeError("Invalid JSON")


def count_nesting_in_bytes(json_bytes: bytes, start: int, end: int) -> int:
	"""
	Return the relative nesting depth between two byte indices.
	"""

	i, nesting = start, 0
	while (i := json_bytes.find(bytes([byte_codes.OPEN_CURLY]), i, end)) != -1:
		if i == 0 or json_bytes[i - 1] != byte_codes.BACKSLASH:
			nesting += 1
		i += 1
	i = start
	while (i := json_bytes.find(bytes([byte_codes.CLOSE_CURLY]), i, end)) != -1:
		if i == 0 or json_bytes[i - 1] != byte_codes.BACKSLASH:
			nesting -= 1
		i += 1
	return nesting


def find_outermost_key_in_json_bytes(json_bytes: bytes, key: str) -> Tuple[int, int]:
	"""
	Return the start and end index of ``"<key>":`` at root-object depth.
	"""

	key_bytes = f'"{key}":'.encode()

	if (curr_i := json_bytes.find(key_bytes, 0)) == -1:
		return (-1, -1)

	key_nest = [(curr_i, count_nesting_in_bytes(json_bytes, 0, curr_i))]

	while (next_i := json_bytes.find(key_bytes, curr_i + len(key_bytes))) != -1:
		nesting = count_nesting_in_bytes(json_bytes, curr_i + len(key_bytes), next_i)
		key_nest.append((next_i, nesting))
		curr_i = next_i

	if len(key_nest) == 1:
		index, level = key_nest[0]
		return (index, index + len(key_bytes)) if level == 1 else (-1, -1)

	for i in range(1, len(key_nest)):
		key_nest[i] = (key_nest[i][0], key_nest[i - 1][1] + key_nest[i][1])

	indices_at_index_one = [i for i, level in key_nest if level == 1]
	if len(indices_at_index_one) != 1:
		return (-1, -1)
	return (indices_at_index_one[0], indices_at_index_one[0] + len(key_bytes))


def detect_indentation_in_json_bytes(json_bytes: bytes, index: int) -> Tuple[int, str]:
	"""
	Detect indentation depth and style at ``index``.
	"""

	indentation_bytes = bytearray()
	contains_tab = False
	for i in range(index - 1, -1, -1):
		if json_bytes[i] not in [byte_codes.SPACE, byte_codes.TAB]:
			break
		if json_bytes[i] == byte_codes.TAB:
			contains_tab = True
		indentation_bytes.insert(0, json_bytes[i])

	if contains_tab:
		return len(indentation_bytes), "\t"
	if indentation_bytes:
		indent_str = indentation_bytes.decode()
		if set(indent_str) == {" "}:
			unit = " " * max(1, len(indent_str))
			if isinstance(config.indent, int) and config.indent > 0:
				unit = " " * config.indent
				return len(indent_str) // config.indent, unit
			return 1, unit
	if isinstance(config.indent, int) and config.indent > 0:
		return 0, " " * config.indent
	if isinstance(config.indent, str) and config.indent:
		return 0, config.indent
	return 0, ""

