class SessionBase:
	in_session: bool
	db_name: str | list[str]
	as_type: Any
	is_closed: bool

	def __init__(self, db_name: str | list[str], as_type: Any):
		self.in_session = False
		self.db_name = db_name
		self.as_type = as_type
		self.write_lock = None
		self.data_handle = {}
		self.is_closed = True

	def __enter__(self) -> SessionBase:
		self.in_session = True
		self.is_closed = False
		self.data_handle = {}
		return self

	def __exit__(self, exc_type, exc_value, traceback) -> None:  # noqa: ANN001
		write_lock = getattr(self, "write_lock", None)
		if write_lock is not None:
			if isinstance(write_lock, list):
				for lock in reversed(write_lock):
					lock._unlock()
			else:
				write_lock._unlock()
		self.write_lock = None
		self.in_session = False
		self.is_closed = True

	def close(self) -> None:
		if not self.is_closed:
			self.__exit__(None, None, None)

	def write(self) -> None:
		if not self.in_session or self.is_closed:
			raise PermissionError("Only call write() inside a with statement.")


@contextmanager
def safe_context(parent: SessionBase, session: SessionBase, *, db_names_to_lock: str | list[str] | None = None):
	"""
	Open a session and guarantee lock cleanup when an exception occurs.
	"""

	parent.__enter__()
	try:
		if isinstance(db_names_to_lock, str):
			session.write_lock = locking.WriteLock(db_names_to_lock)
			session.write_lock._lock()
		elif isinstance(db_names_to_lock, list):
			session.write_lock = [locking.WriteLock(name) for name in db_names_to_lock]
			for lock in session.write_lock:
				lock._lock()
		yield
	except BaseException as exc:
		parent.__exit__(type(exc), exc, exc.__traceback__)
		raise


