def _type_cast(value: Any, as_type: Type[T] | None) -> Any:
	if value is None or as_type is None:
		return value
	if as_type is str and not isinstance(value, str):
		return io_unsafe.serialize_data_to_json_bytes(value).decode()
	return as_type(value)


def _contains_key(obj: Any, wanted_key: str) -> bool:
	if isinstance(obj, dict):
		return wanted_key in obj or any(_contains_key(value, wanted_key) for value in obj.values())
	if isinstance(obj, list):
		return any(_contains_key(value, wanted_key) for value in obj)
	return False


class DDBMethodChooser:
