		path: tuple,
		key: str | None = None,
		where: Callable[[Any, Any], bool] | None = None,
	) -> None:
		path_components = []
		for component in path:
			path_components += component if isinstance(component, list) else [component]
		self.path = "/".join([str(component) for component in path_components])
		self.key = key
		self.where = where
		self.op_type = OperationType(self.path, self.key, self.where)

	def exists(self) -> bool:
		"""
		Check whether the selected file, folder selection, or key exists.
		"""

		if self.where is not None:
			raise RuntimeError("DDB.at(where=...).exists() cannot be used with the where parameter")

		if self.op_type.dir_normal:
			return bool(utils.find_all(self.path))
		if not utils.file_exists(self.path):
			return False
		if self.key is None:
			return True
		data = io_safe.read(self.path)
		return _contains_key(data, self.key)

	def create(self, data: Any = None, force_overwrite: bool = False) -> None:
		"""
		Create a new database file. Existing files require ``force_overwrite=True``.
		"""

		if self.where is not None or self.key is not None or self.op_type.dir:
			raise RuntimeError("DDB.at().create() cannot be used with the where, key, or wildcard path parameters")

		if not force_overwrite and self.exists():
			raise FileExistsError(
				f"Database {self.path} already exists in {config.storage_directory}. Pass force_overwrite=True to overwrite."
			)
		if data is None:
			data = {}
		io_safe.write(self.path, data)

	def delete(self) -> None:
		"""
		Delete the selected file.
		"""

		if self.where is not None or self.key is not None or self.op_type.dir:
			raise RuntimeError("DDB.at().delete() cannot be used with the where, key, or wildcard path parameters")
		io_safe.delete(self.path)

	def read(self, as_type: Type[T] | None = None) -> dict | T | None:
		"""
		Read the selected file, key, or wildcard selection.
		"""

		data: Any = {}

		if self.op_type.file_normal:
			data = io_safe.read(self.path)

		elif self.op_type.file_key:
			data = io_safe.partial_read(self.path, self.key)

		elif self.op_type.file_where:
			file_content = io_safe.read(self.path)
			if file_content is None:
				return None
			for key, value in file_content.items():
				if self.where(key, _type_cast(value, as_type)):
					data[key] = value

		elif self.op_type.dir_normal:
			pattern_paths = utils.find_all(self.path)
			data = {name.split("/")[-1]: io_safe.read(name) for name in pattern_paths}

		elif self.op_type.dir_where:
			for db_name in utils.find_all(self.path):
				key, value = db_name.split("/")[-1], io_safe.read(db_name)
				if self.where(key, _type_cast(value, as_type)):
					data[key] = value

		return _type_cast(data, as_type)

	def read_all(self, as_type: Type[T] | None = None) -> dict | T | None:
		"""Alias for :meth:`read` for compatibility with higher-level examples."""
		return self.read(as_type=as_type)

	def update(self, data: Any) -> Any:
		"""
		Update a file by merging dictionaries or replacing the stored value.
		"""

		if not self.op_type.file_normal:
			raise RuntimeError("DDB.at().update() is only supported for full-file selections")

		with self.session() as (session, current):
			if callable(data):
				new_value = data(current)
				if new_value is not None:
					session.data_handle = new_value
			elif isinstance(current, dict) and isinstance(data, dict):
				current.update(data)
			else:
				session.data_handle = data
			session.write()
		return self.read()

	def session(
		self, as_type: Type[T] | None = None
	) -> SessionFileFull[T] | SessionFileKey[T] | SessionFileWhere[T] | SessionDirFull[T] | SessionDirWhere[T]:
		"""
		Open a transactional session matching the current selection.
		"""

		if self.op_type.file_normal:
			return SessionFileFull(self.path, as_type)
		if self.op_type.file_key:
			return SessionFileKey(self.path, self.key, as_type)
		if self.op_type.file_where:
			return SessionFileWhere(self.path, self.where, as_type)
		if self.op_type.dir_normal:
			return SessionDirFull(self.path, as_type)
		if self.op_type.dir_where:
			return SessionDirWhere(self.path, self.where, as_type)
		raise RuntimeError("Unsupported operation type")

