from __future__ import annotations

import os

import pytest

import dictdatabase as DDB


def _env_bool(name: str, default: bool) -> bool:
	value = os.getenv(name)
	if value is None:
		return default
	return value.strip().lower() in {"1", "true", "yes", "on"}


def _env_indent() -> str | int | None:
	value = os.getenv("DDB_INDENT")
	if value is None:
		return "\t"
	if value.lower() == "none":
		return None
	if value.lower() == "tab":
		return "\t"
	if value.isdigit():
		return int(value)
	return value


