from __future__ import annotations

import random
from typing import Any


def make_complex_nested_random_dict(width: int, depth: int) -> dict[str, Any]:
	"""Create deterministic nested JSON-serializable data for tests."""

	rng = random.Random((width * 1000) + depth)
	leaf_cycle = [None, True, False, 0, 1, -2, 3.5, "text", ["a", 1, None]]

	def build(level: int, prefix: str) -> Any:
		if level <= 0:
			return leaf_cycle[rng.randrange(len(leaf_cycle))]
		result: dict[str, Any] = {}
		for index in range(max(1, min(width, 4))):
			key = f"{prefix}_{level}_{index}"
			selector = (level + index) % 4
			if selector == 0:
				result[key] = build(level - 1, f"{prefix}{index}")
			elif selector == 1:
				result[key] = [build(level - 1, f"{prefix}{index}"), index, f"v{level}_{index}"]
			elif selector == 2:
				result[key] = {"value": build(level - 1, f"{prefix}{index}")}
			else:
				result[key] = leaf_cycle[(index + level) % len(leaf_cycle)]
		return result

	return build(max(1, depth), "node")
